document.querySelectorAll('video').forEach(v=>observer.observe(v));
reduce.addEventListener('change',()=>{if(reduce.matches)finishEntrance();syncVideos()});
narrow.addEventListener('change',syncVideos);document.addEventListener('visibilitychange',syncVideos);
cards.forEach((card,i)=>{
  const button=card.querySelector('button.learn-more');
  button?.addEventListener('click',()=>{
    if(portfolio){parent.postMessage({type:'sqillz-highlight-play',index:i},'*');return}
    $('#detail-heading').textContent=card.querySelector('.card__title').innerText.replace(/\\n/g,' · ');
    $('#detail-copy').textContent=card.querySelector('.dot-number').dataset.dots+' '+card.querySelector('.metric__unit').textContent+' — '+card.querySelector('.caption').innerText.replace(/\\n/g,' ');
    $('dialog').showModal();
  });
});
if(portfolio){
  const stage=$('.stage');
  new ResizeObserver(()=>parent.postMessage({type:'sqillz-highlight-size',height:Math.ceil(stage.getBoundingClientRect().height)},'*')).observe(stage);
}

